<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;
use PDO;
use DomainException;
use InvalidArgumentException;
use DateTimeImmutable;
use DateTimeZone;
use Throwable;
use Kios\MerchantFoundation\{AuthenticatedUserProvider,Identity};
/** Read-only operational reporting. No amounts from orders, no customer/staff secrets or guest notes. */
final class OperationalAnalytics
{
    public function __construct(private PDO $db,private AuthenticatedUserProvider $auth){}
    private function rows(string $sql,array $p=[]):array{$q=$this->db->prepare($sql);$q->execute($p);return $q->fetchAll(PDO::FETCH_ASSOC);}
    public static function period(string $from,string $to):array{
        $dates=[];foreach([$from,$to]as $v){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v,new DateTimeZone('UTC'));if(!$d||$d->format('Y-m-d')!==$v)throw new InvalidArgumentException('Choose valid UTC dates.');$dates[]=$d;}
        $days=(int)$dates[0]->diff($dates[1])->format('%r%a');if($days<0||$days>30)throw new InvalidArgumentException('Choose an inclusive range of at most 31 UTC days.');return [$dates[0]->getTimestamp(),$dates[1]->modify('+1 day')->getTimestamp()];
    }
    public static function csv(array $data):string{
        $f=fopen('php://temp','r+');fputcsv($f,['section','outlet','metric','value','unit','scope'],',','"','');
        foreach(array_merge([['metadata','authorized scope','Snapshot as of',gmdate('Y-m-d H:i:s',$data['asOf']),'UTC','Fresh read-only snapshot']],$data['export'])as $r){$safe=array_map(static function($v){if(is_string($v)&&preg_match('/^\s*[=+@-]/u',$v))return "'".$v;return $v;},$r);fputcsv($f,$safe,',','"','');}rewind($f);return stream_get_contents($f);
    }
    public function load(string $m,string $outlet,string $from,string $to,string $station='',int $page=1):array{
        Identity::validate($m);if($outlet!=='all')Identity::validate($outlet);if($station!==''&&!preg_match('/^[1-9][0-9]{0,8}$/D',$station))throw new InvalidArgumentException('Choose an authorized station.');if($page<1||$page>1000)throw new InvalidArgumentException('Invalid activity page.');[$start,$end]=self::period($from,$to);$now=time();$end=min($end,$now+1);
        (new Entitlements($this->db,$this->auth))->requireFeature($m,$outlet==='all'?($this->rows('SELECT outlet_id FROM merchant_outlets WHERE merchant_id=? AND active=1 ORDER BY outlet_id LIMIT 1',[$m])[0]['outlet_id']??''):$outlet,'analytics','read');if($outlet==='all')(new Entitlements($this->db,$this->auth))->requireFeature($m,$this->rows('SELECT outlet_id FROM merchant_outlets WHERE merchant_id=? AND active=1 ORDER BY outlet_id LIMIT 1',[$m])[0]['outlet_id'],'multi_outlet','read');$actor=$this->auth->currentUserId();if($actor===null)throw new DomainException('Authenticated analytics role required.');
        if($this->db->inTransaction())throw new \LogicException('Analytics owns its read-only snapshot.');$previousZone=(string)$this->db->query('SELECT @@session.time_zone')->fetchColumn();$this->db->exec("SET time_zone='+00:00'");$this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->exec('SET TRANSACTION READ ONLY');$this->db->beginTransaction();
        try{
            $owner=(bool)$this->rows("SELECT r.user_id FROM merchant_memberships r JOIN merchant_staff s ON s.user_id=r.user_id AND s.active=1 JOIN merchant_organizations m ON m.merchant_id=r.merchant_id AND m.active=1 WHERE r.user_id=? AND r.merchant_id=? AND r.role_code='merchant_owner' AND r.active=1",[$actor,$m]);
            $all=$this->rows("SELECT o.outlet_id,o.name,l.legacy_outlet_id FROM merchant_outlets o JOIN merchant_organizations m ON m.merchant_id=o.merchant_id AND m.active=1 JOIN merchant_legacy_outlets l ON l.merchant_id=o.merchant_id AND l.merchant_outlet_id=o.outlet_id JOIN outlets lo ON lo.outlet_id=l.legacy_outlet_id AND lo.active=1 WHERE o.merchant_id=? AND o.active=1 ORDER BY o.name",[$m]);
            if(!$owner){if($outlet==='all')throw new DomainException('Merchant-wide reporting requires merchant ownership.');$grants=$this->rows("SELECT r.outlet_id FROM merchant_outlet_memberships r JOIN merchant_staff s ON s.user_id=r.user_id AND s.active=1 WHERE r.user_id=? AND r.merchant_id=? AND r.active=1 AND r.role_code='outlet_administrator'",[$actor,$m]);$ids=array_column($grants,'outlet_id');$all=array_values(array_filter($all,fn($o)=>in_array($o['outlet_id'],$ids,true)));}
            $selected=$outlet==='all'?$all:array_values(array_filter($all,fn($o)=>$o['outlet_id']===$outlet));if(!$selected||count($selected)>20)throw new DomainException('Authorized reporting scope of 1–20 outlets required.');
            $legacy=array_column($selected,'legacy_outlet_id');$place=implode(',',array_fill(0,count($legacy),'?'));$stations=$this->rows('SELECT station_id,outlet_id,name FROM preparation_stations WHERE outlet_id IN ('.$place.') ORDER BY name',$legacy);if($station!==''&&!in_array($station,array_map('strval',array_column($stations,'station_id')),true))throw new DomainException('Station outside selected outlets.');
            $result=['merchant'=>$m,'outlet'=>$outlet,'outlets'=>$all,'canAggregate'=>$owner,'selected'=>$selected,'from'=>$from,'to'=>$to,'timezone'=>'UTC','asOf'=>$now,'station'=>$station,'stations'=>$stations,'metrics'=>[],'kitchen'=>[],'seating'=>[],'reservations'=>[],'inventory'=>[],'movements'=>[],'trends'=>[],'activity'=>[],'export'=>[],'quality'=>[],'page'=>$page,'activityTotal'=>0];
            foreach($selected as $o){$id=$o['outlet_id'];$lid=(int)$o['legacy_outlet_id'];$name=$o['name'];$args=[$m,$id,$start,$end];
                $created=(int)$this->rows('SELECT COUNT(*) n FROM merchant_service_sessions WHERE merchant_id=? AND outlet_id=? AND created_epoch>=? AND created_epoch<?',$args)[0]['n'];$events=$this->rows("SELECT operation,COUNT(DISTINCT service_id) n FROM merchant_service_events WHERE merchant_id=? AND outlet_id=? AND occurred_epoch>=? AND occurred_epoch<? AND operation IN ('submit','served') GROUP BY operation",$args);$counts=array_column($events,'n','operation');
                foreach(['Internal services created'=>$created,'Kitchen submissions'=>(int)($counts['submit']??0),'Service completions'=>(int)($counts['served']??0)]as $label=>$value){$result['metrics'][]=[$name,$label,$value,'Period events / creation'];$result['export'][]=['overview',$name,$label,$value,'records',$from.' through '.$to.' UTC'];}
                $orderCount=(int)$this->rows("SELECT COUNT(*) n FROM orders WHERE outlet_id=? AND order_mode='INTERNAL_SERVICE' AND created_at>=? AND created_at<?",[$lid,gmdate('Y-m-d H:i:s',$start),gmdate('Y-m-d H:i:s',$end)])[0]['n'];$result['metrics'][]=[$name,'Internal orders created',$orderCount,'Persisted internal orders in period'];$result['export'][]=['overview',$name,'Internal orders created',$orderCount,'orders','INTERNAL_SERVICE order creation in UTC range'];
                $current=$this->rows("SELECT COUNT(DISTINCT CASE WHEN pt.status='queued' AND o.status='preparing' THEN s.order_id END) queued,COUNT(DISTINCT CASE WHEN o.status='ready' THEN s.order_id END) ready FROM merchant_service_sessions s JOIN orders o ON o.order_id=s.order_id AND o.outlet_id=s.legacy_outlet_id LEFT JOIN preparation_tasks pt ON pt.order_id=o.order_id AND pt.outlet_id=o.outlet_id WHERE s.merchant_id=? AND s.outlet_id=? AND s.status='SUBMITTED'",[$m,$id])[0];foreach(['Orders with queued station work'=>(int)$current['queued'],'Ready orders awaiting service'=>(int)$current['ready']]as $label=>$value){$result['metrics'][]=[$name,$label,$value,'Current snapshot'];$result['export'][]=['overview',$name,$label,$value,'orders','Current snapshot; not date-filtered'];}
                $tables=$this->rows('SELECT operational_state,COUNT(*) n FROM merchant_seating_tables WHERE merchant_id=? AND outlet_id=? AND active=1 GROUP BY operational_state',[$m,$id]);foreach($tables as $row){$result['seating'][]=[$name,$row['operational_state'],(int)$row['n']];$result['export'][]=['seating',$name,$row['operational_state'],(int)$row['n'],'tables','Current active table snapshot'];}
                $reservations=$this->rows('SELECT status,COUNT(*) n FROM merchant_seating_reservations WHERE merchant_id=? AND outlet_id=? AND created_epoch>=? AND created_epoch<? GROUP BY status',$args);foreach($reservations as $row){$result['reservations'][]=[$name,$row['status'],(int)$row['n']];$result['export'][]=['reservations',$name,$row['status'],(int)$row['n'],'reservations','Created in range; current lifecycle state'];}
                $pairs=$this->rows("SELECT reservation_id,MIN(CASE WHEN state='SEATED' THEN occurred_epoch END) started,MAX(CASE WHEN state='COMPLETED' THEN occurred_epoch END) finished,SUM(state='SEATED') starts,SUM(state='COMPLETED') ends FROM (SELECT JSON_UNQUOTE(JSON_EXTRACT(result_json,'$.reservation.reservation_id')) reservation_id,JSON_UNQUOTE(JSON_EXTRACT(result_json,'$.reservation.status')) state,occurred_epoch FROM merchant_seating_events WHERE merchant_id=? AND outlet_id=? AND operation='transition' AND occurred_epoch<=?) e GROUP BY reservation_id HAVING finished>=? AND finished<?",[$m,$id,$now,$start,$end]);$valid=[];foreach($pairs as $pair){if($pair['reservation_id']!==null&&(int)$pair['starts']===1&&(int)$pair['ends']===1&&(int)$pair['finished']>=(int)$pair['started'])$valid[]=(int)$pair['finished']-(int)$pair['started'];else $result['quality'][]=$name.': invalid/missing reservation seating-event pair excluded.';}$result['export'][]=['seating',$name,'Reservation seated episode mean',$valid?array_sum($valid)/count($valid):'Unavailable','seconds','Paired SEATED/COMPLETED audit events; completed in range; n='.count($valid)];
                $extra=$station!==''?' AND pt.station_id=?':'';$params=[$lid,gmdate('Y-m-d H:i:s',$start),gmdate('Y-m-d H:i:s',$end)];if($station!=='')$params[]=(int)$station;
                $tasks=$this->rows("SELECT pt.station_id,ps.name,pt.status,pt.preparation_task_id,MIN(CASE WHEN e.to_status='preparing' THEN UNIX_TIMESTAMP(e.changed_at) END) started,MAX(CASE WHEN e.to_status='ready' THEN UNIX_TIMESTAMP(e.changed_at) END) finished,SUM(CASE WHEN e.to_status='preparing' THEN 1 ELSE 0 END) starts,SUM(CASE WHEN e.to_status='ready' THEN 1 ELSE 0 END) ends FROM preparation_tasks pt JOIN preparation_stations ps ON ps.station_id=pt.station_id AND ps.outlet_id=pt.outlet_id LEFT JOIN preparation_task_events e ON e.preparation_task_id=pt.preparation_task_id AND e.outlet_id=pt.outlet_id WHERE pt.outlet_id=? AND pt.created_at>=? AND pt.created_at<?".$extra.' GROUP BY pt.station_id,ps.name,pt.status,pt.preparation_task_id',$params);$groups=[];
                foreach($tasks as $t){$key=$t['station_id'];$g=$groups[$key]??['name'=>$t['name'],'count'=>0,'queued'=>0,'preparing'=>0,'ready'=>0,'valid'=>0,'seconds'=>0,'incomplete'=>0,'invalid'=>0];$g['count']++;$g[$t['status']]++;if((int)$t['starts']===1&&(int)$t['ends']===1&&$t['started']!==null&&(int)$t['finished']>=(int)$t['started']&&(int)$t['finished']<=$now){$g['valid']++;$g['seconds']+=(int)$t['finished']-(int)$t['started'];}elseif((int)$t['ends']===0)$g['incomplete']++;else $g['invalid']++;$groups[$key]=$g;}
                foreach($groups as $g){$result['kitchen'][]=[$name,$g['name'],$g['count'],$g['queued'],$g['preparing'],$g['ready'],$g['valid']?round($g['seconds']/$g['valid'],2):'Unavailable',$g['valid'],$g['incomplete'],$g['invalid']];$result['export'][]=['kitchen',$name,$g['name'].' preparation mean',$g['valid']?$g['seconds']/$g['valid']:'Unavailable','seconds','Task-created cohort; exactly one preparing/ready event; n='.$g['valid']];if($g['invalid'])$result['quality'][]=$name.' / '.$g['name'].': '.$g['invalid'].' invalid timing pairs excluded.';}
                $waits=$this->rows("SELECT s.service_id,e.occurred_epoch served,MIN(UNIX_TIMESTAMP(h.changed_at)) ready,COUNT(h.history_id) ready_events FROM merchant_service_sessions s JOIN merchant_service_events e ON e.merchant_id=s.merchant_id AND e.outlet_id=s.outlet_id AND e.service_id=s.service_id AND e.operation='served' LEFT JOIN order_status_history h ON h.order_id=s.order_id AND h.status='ready' WHERE s.merchant_id=? AND s.outlet_id=? AND e.occurred_epoch>=? AND e.occurred_epoch<? GROUP BY s.service_id,e.occurred_epoch",$args);$durations=[];foreach($waits as $w){if((int)$w['ready_events']===1&&$w['ready']!==null&&(int)$w['served']>=(int)$w['ready'])$durations[]=(int)$w['served']-(int)$w['ready'];else $result['quality'][]=$name.': invalid ready-to-served pair excluded.';}$result['export'][]=['kitchen',$name,'Ready-to-served mean',$durations?array_sum($durations)/count($durations):'Unavailable','seconds','Service completed in range; paired ready history; n='.count($durations)];
                $items=$this->rows('SELECT i.item_id,i.name,i.unit,i.balance_milli,i.minimum_milli,COALESCE(SUM(v.delta_milli),0) ledger FROM merchant_inventory_items i LEFT JOIN merchant_inventory_movements v ON v.merchant_id=i.merchant_id AND v.outlet_id=i.outlet_id AND v.item_id=i.item_id WHERE i.merchant_id=? AND i.outlet_id=? GROUP BY i.item_id,i.name,i.unit,i.balance_milli,i.minimum_milli',[$m,$id]);foreach($items as $item){$balanced=(int)$item['balance_milli']===(int)$item['ledger'];$result['inventory'][]=[$name,$item['name'],$item['unit'],(int)$item['balance_milli'],(int)$item['minimum_milli'],(int)$item['balance_milli']<=(int)$item['minimum_milli']?'Alert':'In stock',$balanced?'MATCH':'MISMATCH'];$result['export'][]=['inventory',$name,$item['name'].' current balance',(int)$item['balance_milli']/1000,$item['unit'],'Current snapshot; ledger '.($balanced?'matches':'MISMATCH')];if(!$balanced)$result['quality'][]=$name.': '.$item['name'].' ledger/balance mismatch.';}
                $moves=$this->rows("SELECT e.operation,origin.operation original_operation,i.unit,SUM(v.delta_milli) delta,COUNT(*) n FROM merchant_inventory_events e JOIN merchant_inventory_movements v ON v.merchant_id=e.merchant_id AND v.outlet_id=e.outlet_id AND v.request_id=e.request_id JOIN merchant_inventory_items i ON i.merchant_id=v.merchant_id AND i.outlet_id=v.outlet_id AND i.item_id=v.item_id LEFT JOIN merchant_inventory_events origin ON origin.merchant_id=e.merchant_id AND origin.outlet_id=e.outlet_id AND origin.request_id=e.reversed_request WHERE e.merchant_id=? AND e.outlet_id=? AND e.occurred_epoch>=? AND e.occurred_epoch<? GROUP BY e.operation,origin.operation,i.unit",$args);foreach($moves as $v){$op=$v['operation'].($v['operation']==='reverse'?':'.$v['original_operation']:'');$result['movements'][]=[$name,$op,$v['unit'],(int)$v['delta']/1000,(int)$v['n']];$result['export'][]=['movements',$name,$op,(int)$v['delta']/1000,$v['unit'],'Signed ledger movement in UTC period; reversals separately attributed'];}
                $trend=$this->rows("SELECT DATE_FORMAT(FROM_UNIXTIME(e.occurred_epoch),'%Y-%m-%d') day,i.unit,SUM(v.delta_milli) delta FROM merchant_inventory_events e JOIN merchant_inventory_movements v ON v.merchant_id=e.merchant_id AND v.outlet_id=e.outlet_id AND v.request_id=e.request_id JOIN merchant_inventory_items i ON i.merchant_id=v.merchant_id AND i.outlet_id=v.outlet_id AND i.item_id=v.item_id WHERE e.merchant_id=? AND e.outlet_id=? AND e.occurred_epoch>=? AND e.occurred_epoch<? GROUP BY day,i.unit ORDER BY day",$args);foreach($trend as $v){$result['trends'][]=[$name,$v['day'],$v['unit'],(int)$v['delta']/1000];$result['export'][]=['trend',$name,$v['day'],(int)$v['delta']/1000,$v['unit'],'Signed daily ledger delta UTC'];}
                foreach(['merchant_service_events'=>'service','merchant_seating_events'=>'seating','merchant_inventory_events'=>'inventory']as $table=>$type){$events=$this->rows('SELECT actor_id,operation,COUNT(*) n FROM '.$table.' WHERE merchant_id=? AND outlet_id=? AND occurred_epoch>=? AND occurred_epoch<? GROUP BY actor_id,operation',$args);foreach($events as $v){$result['activity'][]=[$name,$type,$v['actor_id'],$v['operation'],(int)$v['n']];}}
                $prep=$this->rows('SELECT e.changed_by actor_id,e.to_status operation,COUNT(*) n FROM preparation_task_events e WHERE e.outlet_id=? AND e.changed_at>=? AND e.changed_at<? GROUP BY e.changed_by,e.to_status',[$lid,gmdate('Y-m-d H:i:s',$start),gmdate('Y-m-d H:i:s',$end)]);foreach($prep as $v)$result['activity'][]=[$name,'kitchen',$v['actor_id'],$v['operation'],(int)$v['n']];
            }
            foreach($result['activity']as $v)$result['export'][]=['staff activity',$v[0],$v[1].' / '.$v[3].' / actor '.$v[2],$v[4],'events','UTC period; activity counts, not attendance/productivity'];$result['activityTotal']=count($result['activity']);usort($result['activity'],fn($a,$b)=>[$a[0],$a[1],$a[2],$a[3]]<=>[$b[0],$b[1],$b[2],$b[3]]);$result['activity']=array_slice($result['activity'],($page-1)*25,25);
            $result['quality'][]='Manual-table occupancy duration is unavailable; no guessed start/end times. Reservation episode durations use actual paired audit events, including any table transfers.';$this->db->commit();return $result;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}finally{$q=$this->db->prepare('SET time_zone=?');$q->execute([$previousZone]);}
    }
}
